82: function loadState() {
83:   try {
84:     const raw = localStorage.getItem(STORAGE_KEY)
85:     if (!raw) return { mapping: emptyMapping(), settings: structuredClone(DEFAULT_SETTINGS) }
86:     const parsed = JSON.parse(raw)
87:     const mapping = emptyMapping()
88:     for (const group of ['deckA', 'deckB', 'mixer']) {
89:       if (parsed.mapping && parsed.mapping[group]) mapping[group] = parsed.mapping[group]
90:     }
91:     return {
92:       mapping,
93:       settings: {
94:         ...structuredClone(DEFAULT_SETTINGS),
95:         ...(parsed.settings || {}),
96:         encoding: { ...DEFAULT_SETTINGS.encoding, ...(parsed.settings?.encoding || {}) },
97:         platterMode: { ...DEFAULT_SETTINGS.platterMode, ...(parsed.settings?.platterMode || {}) },
98:         ticksPerRev: { ...DEFAULT_SETTINGS.ticksPerRev, ...(parsed.settings?.ticksPerRev || {}) }
99:       }
100:     }
101:   } catch {
102:     return { mapping: emptyMapping(), settings: structuredClone(DEFAULT_SETTINGS) }
103:   }
104: }
