106: function bindingMatches(binding, message) {
107:   if (!binding || !message) return false
108:   if (binding.channel !== null && binding.channel !== undefined && binding.channel !== message.channel) return false
109:   if (binding.type === 'pitchbend') return message.type === 'pitchbend'
110:   if (binding.type === 'cc') return message.type === 'cc' && binding.number === message.controller
111:   if (binding.type === 'note') {
112:     return (message.type === 'noteon' || message.type === 'noteoff') && binding.number === message.note
113:   }
114:   return false
115: }
