117: export class MidiManager {
118:   constructor({ onControl, onDevices, onMonitor, onLearn, onNotice, onSettings } = {}) {
119:     const loaded = loadState()
120:     this.mapping = loaded.mapping
121:     this.settings = loaded.settings
122:     this.onControl = onControl || (() => {})
123:     this.onDevices = onDevices || (() => {})
124:     this.onMonitor = onMonitor || (() => {})
125:     this.onLearn = onLearn || (() => {})
126:     this.onNotice = onNotice || (() => {})
127:     this.onSettings = onSettings || (() => {})
128:     this.access = null
129:     this.enabled = false
130:     this.error = ''
131:     this.learning = null
132:     this.capture = null
133:     this.captureHistory = []
134:     this.lastCC = new Map()
135:     this.buttonEdges = new Map()
136:     this.devices = []
137:     this.virtualEnabled = false
138:     this.captureHistory = []
139:   }
140: 
141:   get supported() {
142:     return typeof navigator !== 'undefined' && Boolean(navigator.requestMIDIAccess)
143:   }
144: 
145:   async enable() {
146:     if (!this.supported) {
147:       this.error = 'Web MIDI is not available in this browser. Use Chrome or Edge over HTTPS/localhost.'
148:       this.emitDevices()
149:       return false
150:     }
151:     if (this.access) {
152:       this.attachAccess()
153:       return true
154:     }
155:     try {
156:       this.access = await navigator.requestMIDIAccess({ sysex: false })
157:       this.enabled = true
158:       this.error = ''
159:       this.attachAccess()
160:       return true
161:     } catch (error) {
162:       this.enabled = false
163:       this.error = error && error.name === 'SecurityError'
164:         ? 'MIDI access was blocked. Allow MIDI permission and try again.'
165:         : 'Could not open MIDI devices.'
166:       this.emitDevices()
167:       return false
168:     }
169:   }
170: 
171:   attachAccess() {
172:     if (!this.access) return
173:     this.access.onstatechange = () => this.attachAccess()
174:     for (const input of this.access.inputs.values()) {
175:       input.onmidimessage = (event) => this.handleRaw(event.data, input.name)
176:     }
177:     this.devices = Array.from(this.access.inputs.values()).map((input) => ({
178:       id: input.id,
179:       name: input.name,
180:       manufacturer: input.manufacturer,
181:       state: input.state,
182:       connection: input.connection
183:     }))
184:     if (!this.settings.lastController && this.devices[0]) {
185:       this.settings.lastController = this.devices[0].name
186:       this.save()
187:     }
188:     this.emitDevices()
189:   }
190: 
191:   emitDevices() {
192:     this.onDevices({
193:       supported: this.supported,
194:       enabled: this.enabled,
195:       error: this.error,
196:       devices: this.devices,
197:       virtualEnabled: this.virtualEnabled
198:     })
199:   }
200: 
201:   setVirtualEnabled(enabled) {
202:     this.virtualEnabled = Boolean(enabled)
203:     this.emitDevices()
204:   }
205: 
206:   hasTouch(deckId) {
207:     const group = deckId === 'A' || deckId === 'B' ? `deck${deckId}` : deckId
208:     return Boolean(this.mapping[group]?.touch)
209:   }
210: 
211:   getBinding(targetId) {
212:     const [group, target] = String(targetId).split('.')
213:     return this.mapping[group]?.[target] || null
214:   }
215: 
216:   setBinding(targetId, binding, { silent = false } = {}) {
217:     const [group, target] = String(targetId).split('.')
218:     if (!this.mapping[group]) this.mapping[group] = {}
219:     if (binding) {
220:       // A physical control should only own one target in its group.
221:       for (const key of Object.keys(this.mapping[group])) {
222:         const existing = this.mapping[group][key]
223:         if (
224:           key !== target &&
225:           existing &&
226:           existing.type === binding.type &&
227:           existing.channel === binding.channel &&
228:           existing.number === binding.number
229:         ) {
230:           delete this.mapping[group][key]
231:         }
232:       }
233:     }
234:     if (binding) this.mapping[group][target] = binding
235:     else delete this.mapping[group][target]
236:     this.save()
237:     if (!silent) {
238:       this.onNotice?.(binding ? `Mapped ${targetId.replace('.', ' ')} → ${formatBinding(binding)}` : `Cleared ${targetId.replace('.', ' ')}`)
239:     }
240:     this.onLearn?.(null)
241:   }
242: 
243:   clearBinding(targetId) {
244:     this.setBinding(targetId, null)
245:   }
246: 
247:   clearAll() {
248:     this.mapping = emptyMapping()
249:     this.learning = null
250:     this.save()
251:     this.onLearn?.(null)
252:     this.onNotice?.('All MIDI mappings cleared')
253:   }
254: 
255:   startLearn(targetId) {
256:     this.learning = { targetId }
257:     this.onLearn?.(targetId)
258:   }
259: 
260:   cancelLearn() {
261:     this.learning = null
262:     this.onLearn?.(null)
263:   }
264: 
265:   save() {
266:     try {
267:       localStorage.setItem(STORAGE_KEY, JSON.stringify({ mapping: this.mapping, settings: this.settings }))
268:     } catch {
269:       /* storage can be unavailable in private mode */
270:     }
271:     this.onSettings?.(this.settings)
272:   }
273: 
274:   updateSetting(path, value) {
275:     const [key, deck] = path.split('.')
276:     if (deck) this.settings[key][deck] = value
277:     else this.settings[key] = value
278:     this.save()
279:   }
280: 
281:   handleRaw(data, sourceName = 'Unknown input', sourceKind = 'hardware') {
282:     let message
283:     try {
284:       message = parseMidiMessage(data)
285:     } catch {
286:       return null
287:     }
288:     if (!message || message.type === 'clock' || message.type === 'sysex') return message
289: 
290:     const map = sourceKind === 'virtual' ? VIRTUAL_MAPPING : this.mapping
291:     const matches = []
292:     for (const group of ['deckA', 'deckB', 'mixer']) {
293:       const groupMap = map[group]
294:       if (!groupMap) continue
295:       for (const [target, binding] of Object.entries(groupMap)) {
296:         if (bindingMatches(binding, message)) matches.push({ targetId: `${group}.${target}`, group, target, binding })
297:       }
298:     }
299: 
300:     let relativeDelta = null
301:     for (const match of matches) {
302:       if (match.target === 'jog') {
303:         const key = `${sourceName}|${sourceKind}|${message.channel}|${message.controller}`
304:         const last = this.lastCC.get(key)
305:         relativeDelta = decodeRelative(message.value, this.settings.encoding[match.group === 'deckA' ? 'A' : 'B'], last)
306:         this.lastCC.set(key, message.value)
307:       }
308:     }
309: 
310:     const monitorEntry = {
311:       time: Date.now(),
312:       source: sourceName,
313:       kind: sourceKind,
314:       message,
315:       text: describeMidiMessage(message),
316:       delta: relativeDelta,
317:       raw: message.raw
318:     }
319:     this.onMonitor(monitorEntry)
320: 
321:     if (this.capture) {
322:       this.captureHistory.push(monitorEntry)
323:       if (this.capture.predicate(message, monitorEntry, this.captureHistory)) {
324:         const resolve = this.capture.resolve
325:         clearTimeout(this.capture.timer)
326:         this.capture = null
327:         resolve(monitorEntry)
328:       }
329:     }
330: 
331:     if (this.learning) {
332:       const learned = this.learnFromMessage(this.learning.targetId, message)
333:       if (learned) return message
334:     }
335: 
336:     for (const match of matches) {
337:       const payload = this.payloadFor(match, message, relativeDelta, sourceName, sourceKind)
338:       if (payload) this.onControl(match.targetId, payload)
339:     }
340:     return message
341:   }
342: 
343:   payloadFor(match, message, relativeDelta, sourceName, sourceKind) {
344:     const base = { message, source: sourceName, sourceKind, raw: message.raw }
345:     switch (match.target) {
346:       case 'jog':
347:         return { ...base, delta: relativeDelta || 0, rawValue: message.value }
348:       case 'touch': {
349:         if (message.type === 'noteon') return { ...base, pressed: message.velocity > 0 }
350:         if (message.type === 'noteoff') return { ...base, pressed: false }
351:         if (message.type === 'cc') return { ...base, pressed: message.value >= 64 }
352:         return null
353:       }
354:       case 'play':
355:       case 'cue':
356:       case 'sync':
357:       case 'pad1':
358:       case 'pad2':
359:       case 'pad3':
360:       case 'pad4': {
361:         const key = `${match.targetId}|${sourceName}|${sourceKind}`
362:         let pressed = false
363:         if (message.type === 'noteon') pressed = message.velocity > 0
364:         else if (message.type === 'noteoff') pressed = false
365:         else if (message.type === 'cc') pressed = message.value >= 64
366:         const previous = this.buttonEdges.get(key) || false
367:         this.buttonEdges.set(key, pressed)
368:         if (!pressed || previous) return null
369:         return { ...base, pressed: true }
370:       }
371:       case 'tempo': {
372:         const unit = message.type === 'pitchbend' ? pitchBendUnit(message) : midiUnit(message.value)
373:         return { ...base, unit, pitch: message.type === 'pitchbend' ? unit * 0.08 : (unit - 0.5) * 0.16 }
374:       }
375:       case 'crossfader':
376:         return { ...base, unit: midiUnit(message.value), value: midiUnit(message.value) * 2 - 1 }
377:       case 'master':
378:         return { ...base, unit: midiUnit(message.value) }
379:       case 'volume':
380:       case 'filter':
381:       case 'eqHigh':
382:       case 'eqMid':
383:       case 'eqLow':
384:         return { ...base, unit: midiUnit(message.value) }
385:       default:
386:         return null
387:     }
388:   }
389: 
390:   learnFromMessage(targetId, message) {
391:     let type = null
392:     if (message.type === 'cc') type = 'cc'
393:     else if (message.type === 'noteon' || message.type === 'noteoff') type = 'note'
394:     else if (message.type === 'pitchbend') type = 'pitchbend'
395:     if (!type) return false
396:     // Do not learn note-off as the binding moment, but accept the note id.
397:     const binding = {
398:       type,
399:       channel: message.channel,
400:       number: type === 'pitchbend' ? 0 : type === 'cc' ? message.controller : message.note
401:     }
402:     this.learning = null
403:     this.setBinding(targetId, binding, { silent: true })
404:     this.onNotice?.(`${targetId.replace('.', ' ')} mapped to ${formatBinding(binding)}`)
405:     this.onLearn?.(null)
406:     return true
407:   }
408: 
409:   captureNext(predicate, { timeout = 12000 } = {}) {
410:     this.cancelCapture()
411:     return new Promise((resolve, reject) => {
412:       const timer = setTimeout(() => {
413:         this.capture = null
414:         reject(new Error('timeout'))
415:       }, timeout)
416:       this.capture = {
417:         predicate,
418:         resolve,
419:         reject,
420:         timer,
421:         startedAt: Date.now()
422:       }
423:       this.captureHistory = []
424:     })
425:   }
426: 
427:   cancelCapture() {
428:     if (this.capture) {
429:       clearTimeout(this.capture.timer)
430:       const reject = this.capture.reject
431:       this.capture = null
432:       reject?.(new Error('cancelled'))
433:     }
434:   }
435: 
436:   sendVirtual(bytes) {
437:     this.handleRaw(bytes, 'ScratchLab Virtual', 'virtual')
438:   }
439: 
440:   getStatusText() {
441:     if (!this.supported) return 'WEB MIDI UNSUPPORTED'
442:     if (this.error) return this.error.toUpperCase()
443:     if (this.virtualEnabled && (!this.enabled || !this.devices.length)) return 'VIRTUAL MIDI ACTIVE'
444:     if (!this.enabled) return 'MIDI NOT CONNECTED'
445:     if (!this.devices.length) return 'NO MIDI INPUTS'
446:     if (this.devices.length === 1) return this.devices[0].name.toUpperCase()
447:     return `${this.devices.length} MIDI INPUTS`
448:   }
449: }

