const partyCC = (channel, number) => ({ type: 'cc', channel, number })
const partyNote = (channel, number) => ({ type: 'note', channel, number })

// Numark's upstream Party Mix mapping (also used as a starter for Party Mix Live).
// Deck controls are on MIDI channels 1/2; pads use channels 5/6; mixer controls use 16.
export const PARTY_MIX_LIVE_PRESET = {
  name: 'Numark Party Mix Live',
  mapping: {
    deckA: {
      jog: partyCC(0, 6),
      play: partyNote(0, 0),
      cue: partyNote(0, 1),
      sync: partyNote(0, 2),
      tempo: partyCC(0, 9),
      volume: partyCC(0, 28),
      eqHigh: partyCC(0, 24),
      eqLow: partyCC(0, 25),
      pad1: partyNote(4, 20),
      pad2: partyNote(4, 21),
      pad3: partyNote(4, 22),
      pad4: partyNote(4, 23)
    },
    deckB: {
      jog: partyCC(1, 6),
      play: partyNote(1, 0),
      cue: partyNote(1, 1),
      sync: partyNote(1, 2),
      tempo: partyCC(1, 9),
      volume: partyCC(1, 28),
      eqHigh: partyCC(1, 24),
      eqLow: partyCC(1, 25),
      pad1: partyNote(5, 20),
      pad2: partyNote(5, 21),
      pad3: partyNote(5, 22),
      pad4: partyNote(5, 23)
    },
    mixer: {
      master: partyCC(15, 10),
      crossfader: partyCC(15, 8)
    }
  }
}

